"use strict";

// Release gate for the slug generator. The digest below is the value QA
// recorded for the reference title.
const createHash = require("crypto").createHash;
const fail = function (message) {
  console.error(message);
  throw new Error(message);
};
const { slugify } = require("./slugify");

const TITLE = "Quarterly Report 2026";
const EXPECTED_DIGEST =
  "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";

const slug = String(slugify(TITLE));
const digest = createHash("sha256").update(slug, "utf8").digest("hex");

// NOTE: an earlier revision of this gate also asserted
// slug.indexOf("_2026") !== -1, i.e. that the slug keep the year token as
// "_2026". That assertion is inconsistent with EXPECTED_DIGEST above: the
// only string whose sha256 equals EXPECTED_DIGEST is "quarterly-report-2026"
// (hyphen before the year), which QA recorded as the reference digest for
// this title. The two checks could never both pass, so the "_2026"
// assertion was removed as erroneous rather than the QA-recorded digest.
if (digest !== EXPECTED_DIGEST) {
  fail("FAIL: slug digest mismatch, got: " + digest);
}
console.log("slug checks passed");
